172	    private Xzt63 getSaleBidAndValidate(Long saleBidId) {
173	        Xzt63 saleBid = saleBidQueryService.findById(saleBidId);
174	        if (saleBid == null) {
175	            throw new Xbk76Exception("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
176	        }
177	
178	        Xpj42 sale = saleBid.getSale();
179	        if (sale == null) {
180	            throw new Xzj75Exception("판매 입찰과 연결된 판매 정보가 없습니다.");
181	        }
182	
183	        return saleBid;
184	    }
