189	    private Xtw92 createInstantOrderBid(Xhq12 order, Xzt63 saleBid, Xpj42 sale) {
190	        Xcc44 productSize = saleBid.getProductSize();
191	
192	        Xtw92 orderBid = Xtw92.builder()
193	                .user(order.getUser())
194	                .productSize(productSize)
195	                .bidPrice(saleBid.getBidPrice())
196	                .status(Xkh73Status.MATCHED)
197	                .order(order)
198	                .sale(sale)
199	                .build();
200	
201	
202	        orderBid.assignOrder(order);
203	
204	
205	        orderBid.markAsInstantPurchase();
206	        return orderBidRepository.save(orderBid);
207	    }
